const escapeTicket=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function ticketNumber(number){if(!Number.isInteger(number)||number<1||number>10000000)throw Error('Número de ticket inválido.');return String(number).padStart(5,'0');}
export function ticketCode(number){return `TK-${ticketNumber(number)}-ABX`;}
export function parseTicketCode(value){const match=String(value).trim().toUpperCase().match(/^(?:TK-(\d{1,8})-ABX|#?(\d{1,8}))$/);if(!match)return null;const n=Number(match[1]||match[2]);return Number.isInteger(n)&&n>0&&n<=10000000?n:null;}
export function ticketQR(number){const qr=globalThis.qrcode(0,'M');qr.addData(ticketCode(number),'Alphanumeric');qr.make();return qr;}
export function qrSvg(number){return ticketQR(number).createSvgTag({cellSize:4,margin:16,scalable:true});}
export function ticketMarkup(number,name,withQR=true,visit=null){return `<article class="paper-ticket ${withQR?'':'no-qr'}" aria-label="Ticket ${ticketNumber(number)}"><div class="paper-heading"><span>TICKET</span><strong class="paper-number ${number>=100000?'long-number':''}">${ticketNumber(number)}</strong></div>${withQR?`<div class="paper-qr" aria-label="QR del ticket ${ticketNumber(number)}">${qrSvg(number)}</div>`:''}${visit?`<div class="paper-visit"><strong>${escapeTicket(visit.plate)}</strong><span>${escapeTicket(new Date(visit.entry).toLocaleString('es-PE',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}))}</span></div>`:''}</article>`;}
export function ticketSheets(from,to,name,withQR=true,perPage=20){if(!Number.isInteger(from)||!Number.isInteger(to)||from<1||to<from||to>10000000||to-from>=500||![15,20,30].includes(perPage))throw Error('Elige un rango de hasta 500 tickets y 15, 20 o 30 por hoja.');const pages=[];for(let first=from;first<=to;first+=perPage){const last=Math.min(to,first+perPage-1);pages.push(`<section class="ticket-page"><div class="ticket-sheet" data-per-page="${perPage}">${Array.from({length:last-first+1},(_,i)=>ticketMarkup(first+i,name,withQR)).join('')}</div></section>`);}return pages.join('');}
export const ticketStyles=`.paper-ticket{box-sizing:border-box;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:10px;background:#fff;color:#000;border:1px dashed #aaa;border-radius:8px;padding:18px 12px;text-align:center;font-family:"Courier New",monospace;break-inside:avoid;overflow:hidden}.paper-heading>span{display:block;font-size:10px;letter-spacing:2px;line-height:1.3}.paper-number{font-size:42px;line-height:1.1;font-weight:700;white-space:nowrap;letter-spacing:1px;display:block;margin-top:4px}.paper-number.long-number{font-size:32px;letter-spacing:0}.paper-qr{width:160px;height:160px}.paper-qr svg{width:100%;height:100%;display:block;shape-rendering:crispEdges}.paper-visit{display:flex;flex-direction:column;gap:4px;font-size:12px;margin-top:5px}.paper-visit span{font-size:10px}.paper-ticket.no-qr{min-height:170px}.ticket-sheet{--columns:4;--rows:5;--qr-size:32mm;--number-size:29px;display:grid;grid-template-columns:repeat(var(--columns),minmax(0,1fr));grid-auto-rows:54.6mm;gap:2mm;align-content:start}.ticket-sheet .paper-ticket{width:100%;height:100%;min-height:0;padding:2mm;gap:1mm;border-radius:2mm;box-shadow:none}.ticket-sheet .paper-heading>span{font-size:7px;letter-spacing:1px}.ticket-sheet .paper-number{font-size:var(--number-size);margin-top:1mm;letter-spacing:.4px}.ticket-sheet .paper-number.long-number{font-size:calc(var(--number-size) - 5px);letter-spacing:0}.ticket-sheet .paper-qr{width:var(--qr-size);height:var(--qr-size);flex-shrink:0}.ticket-sheet[data-per-page="15"]{--columns:3;--rows:5;--qr-size:27mm;--number-size:29px}.ticket-sheet[data-per-page="30"]{--columns:5;--rows:6;--qr-size:26mm;--number-size:26px;grid-auto-rows:45.16mm}.ticket-sheet .paper-visit{font-size:8px}.ticket-sheet .paper-visit span{font-size:7px}.ticket-page{margin:0 0 8mm;break-after:page;page-break-after:always}.ticket-page:last-child{margin-bottom:0;break-after:auto;page-break-after:auto}@media print{@page{size:A4 portrait;margin:8mm}html,body{padding:0!important;margin:0!important}.ticket-page{margin:0;width:194mm;height:281mm;overflow:hidden}.ticket-sheet{height:100%;width:100%}}`;


